module graph_orientation_4bit(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] m,\n    input [31:0] edges,\n    output reg yes_no,\n    output reg [7:0] orient_0,\n    output reg [7:0] orient_1,\n    output reg [7:0] orient_2,\n    output reg [7:0] orient_3,\n    output reg done\n);\n    \n    // State declarations\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] BUILD_ORIENT= 4'd1;\n    localparam [3:0] FLOYD_INIT  = 4'd2;\n    localparam [3:0] FLOYD_K_LOOP= 4'd3;\n    localparam [3:0] FLOYD_I_LOOP= 4'd4;\n    localparam [3:0] FLOYD_J_LOOP= 4'd5;\n    localparam [3:0] CHECK_STRONG= 4'd6;\n    localparam [3:0] NEXT_ORIENT = 4'd7;\n    localparam [3:0] OUTPUT      = 4'd8;\n\n    reg [3:0] state;\n\n    // Edge storage\n    reg [3:0] u0, u1, u2, u3;\n    reg [3:0] v0, v1, v2, v3;\n    reg [2:0] stored_m;\n\n    // Orientation counter\n    reg [3:0] orient_cnt;\n    reg found;\n\n    // Oriented edge storage (for output)\n    reg [3:0] found_from0, found_to0;\n    reg [3:0] found_from1, found_to1;\n    reg [3:0] found_from2, found_to2;\n    reg [3:0] found_from3, found_to3;\n\n    // Adjacency matrix\n    reg [15:0] adj_matrix;\n    reg [15:0] temp_adj_matrix;\n\n    // Loop counters\n    reg [1:0] k_count;\n    reg [1:0] i_count;\n    reg [1:0] j_count;\n\n    // Timeout counter\n    reg [10:0] cycle_counter;\n    localparam [10:0] MAX_CYCLES = 11'd2000;\n\n    // Current oriented edges (temporary)\n    reg [3:0] from0, from1, from2, from3;\n    reg [3:0] to0, to1, to2, to3;\n\n    // Combinational strong connectivity check\n    wire is_strong = &adj_matrix;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            yes_no <= 1'b0;\n            done <= 1'b0;\n            orient_cnt <= 4'd0;\n            found <= 1'b0;\n            orient_0 <= 8'd0;\n            orient_1 <= 8'd0;\n            orient_2 <= 8'd0;\n            orient_3 <= 8'd0;\n            cycle_counter <= 11'd0;\n            adj_matrix <= 16'd0;\n            k_count <= 2'd0;\n            i_count <= 2'd0;\n            j_count <= 2'd0;\n        end else begin\n            done <= 1'b0;\n            cycle_counter <= cycle_counter + 11'd1;\n            if (cycle_counter > MAX_CYCLES) begin\n                state <= OUTPUT;\n                yes_no <= 1'b0;\n            end else\n            case (state)\n                IDLE: begin\n                    cycle_counter <= 11'd0;\n                    if (start) begin\n                        u0 <= edges[31:28];\n                        v0 <= edges[27:24];\n                        u1 <= edges[23:20];\n                        v1 <= edges[19:16];\n                        u2 <= edges[15:12];\n                        v2 <= edges[11:8];\n                        u3 <= edges[7:4];\n                        v3 <= edges[3:0];\n                        stored_m <= m;\n                        orient_cnt <= 4'd0;\n                        found <= 1'b0;\n                        state <= BUILD_ORIENT;\n                    end\n                end\n\n                BUILD_ORIENT: begin\n                    // Edge 0\n                    if (stored_m > 3'd0) begin\n                        from0 = orient_cnt[0] ? v0 : u0;\n                        to0   = orient_cnt[0] ? u0 : v0;\n                    end else begin\n                        from0 = 4'd0;\n                        to0   = 4'd0;\n                    end\n                    // Edge 1\n                    if (stored_m > 3'd1) begin\n                        from1 = orient_cnt[1] ? v1 : u1;\n                        to1   = orient_cnt[1] ? u1 : v1;\n                    end else begin\n                        from1 = 4'd0;\n                        to1   = 4'd0;\n                    end\n                    // Edge 2\n                    if (stored_m > 3'd2) begin\n                        from2 = orient_cnt[2] ? v2 : u2;\n                        to2   = orient_cnt[2] ? u2 : v2;\n                    end else begin\n                        from2 = 4'd0;\n                        to2   = 4'd0;\n                    end\n                    // Edge 3\n                    if (stored_m > 3'd3) begin\n                        from3 = orient_cnt[3] ? v3 : u3;\n                        to3   = orient_cnt[3] ? u3 : v3;\n                    end else begin\n                        from3 = 4'd0;\n                        to3   = 4'd0;\n                    end\n                    state <= FLOYD_INIT;\n                end\n\n                FLOYD_INIT: begin\n                    // Set initial adj_matrix (diagonal above)\n                    adj_matrix <= 16'b1000010000100001;\n                    if (stored_m > 3'd0) adj_matrix[from0*4 + to0] <= 1'b1;\n                    if (stored_m > 3'd1) adj_matrix[from1*4 + to1] <= 1'b1;\n                    if (stored_m > 3'd2) adj_matrix[from2*4 + to2] <= 1'b1;\n                    if (stored_m > 3'd3) adj_matrix[from3*4 + to3] <= 1'b1;\n                    k_count <= 2'd0;\n                    state <= FLOYD_K_LOOP;\n                end\n\n                FLOYD_K_LOOP: begin\n                    temp_adj_matrix <= adj_matrix;\n                    i_count <= 2'd0;\n                    state <= FLOYD_I_LOOP;\n                end\n\n                FLOYD_I_LOOP: begin\n                    j_count <= 2'd0;\n                    state <= FLOYD_J_LOOP;\n                end\n\n                FLOYD_J_LOOP: begin\n                    // Floyd-Warshall update\n                    if (i_count <= 2'd3 && k_count <= 2'd3) begin\n                        adj_matrix[i_count*4 + j_count] <=\n                            temp_adj_matrix[i_count*4 + j_count] | \n                            (temp_adj_matrix[i_count*4 + k_count] & temp_adj_matrix[k_count*4 + j_count]);\n                    end\n                    // Increment j_count\n                    if (j_count >= 2'd3) begin\n                        j_count <= 2'd0;\n                        // Increment i_count\n                        if (i_count >= 2'd3) begin\n                            i_count <= 2'd0;\n                            // Increment k_count\n                            if (k_count >= 2'd3) begin\n                                k_count <= 2'd0;\n                                state <= CHECK_STRONG;\n                            end else begin\n                                k_count <= k_count + 2'd1;\n                                state <= FLOYD_K_LOOP;\n                            end\n                        end else begin\n                            i_count <= i_count + 2'd1;\n                            state <= FLOYD_I_LOOP;\n                        end\n                    end else begin\n                        j_count <= j_count + 2'd1;\n                    end\n                end\n\n                CHECK_STRONG: begin\n                    if (is_strong) begin\n                        found <= 1'b1;\n                        found_from0 <= from0;\n                        found_to0   <= to0;\n                        found_from1 <= from1;\n                        found_to1   <= to1;\n                        found_from2 <= from2;\n                        found_to2   <= to2;\n                        found_from3 <= from3;\n                        found_to3   <= to3;\n                        state <= OUTPUT;\n                    end else begin\n                        state <= NEXT_ORIENT;\n                    end\n                end\n\n                NEXT_ORIENT: begin\n                    if (orient_cnt < (11'd1 << stored_m) - 11'd1) begin\n                        orient_cnt <= orient_cnt + 4'd1;\n                        state <= BUILD_ORIENT;\n                    end else begin\n                        state <= OUTPUT;\n                    end\n                end\n\n                OUTPUT: begin\n                    yes_no <= found;\n                    done   <= 1'b1;\n                    orient_0 <= {found_from0, found_to0};\n                    orient_1 <= {found_from1, found_to1};\n                    orient_2 <= {found_from2, found_to2};\n                    orient_3 <= {found_from3, found_to3};\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule